def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Locate the monochromatic diagonal pair that marks the line to continue.
    pts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0 and v not in pts:
                pts[v] = []
            if v != 0:
                pts[v].append((r, c))
    candidates = []
    for color, cells in pts.items():
        for i, (r1, c1) in enumerate(cells):
            for r2, c2 in cells[i + 1:]:
                if abs(r2-r1) == 1 and abs(c2-c1) == 1:
                    dr, dc = r2-r1, c2-c1
                    # Continue from the end further along the diagonal.
                    end = max(cells, key=lambda p: p[0]*dr + p[1]*dc)
                    candidates.append((color, dr, dc, end))
    if not candidates:
        return out
    # ARC examples mark continuation with the uniquely paired color; select the
    # diagonal pair color whose ray extends toward the edge.
    color, dr, dc, end = candidates[0]
    r, c = end[0]+dr, end[1]+dc
    while 0 <= r < h and 0 <= c < w:
        if grid[r][c] != 0 and grid[r][c] != color:
            break
        out[r][c] = color
        r += dr
        c += dc
    return out
